/**
 * Vendored Standalone Chart Engine (Chart.js API Compatible)
 * Self-hosted local LAN visualization engine with ZERO CDN or external internet dependencies.
 * Supports: grouped/stacked bars, line charts, tooltips, responsive resizing, and legends.
 */

(function (root, factory) {
    if (typeof define === 'function' && define.amd) {
        define([], factory);
    } else if (typeof module === 'object' && module.exports) {
        module.exports = factory();
    } else {
        root.Chart = factory();
    }
}(typeof self !== 'undefined' ? self : this, function () {

    class Chart {
        constructor(canvas, config) {
            this.canvas = typeof canvas === 'string' ? document.getElementById(canvas) : canvas;
            if (!this.canvas) throw new Error("Canvas element not found");
            this.ctx = this.canvas.getContext('2d');
            this.config = config || {};
            this.type = this.config.type || 'bar';
            this.data = this.config.data || { labels: [], datasets: [] };
            this.options = this.config.options || {};

            this.tooltip = null;
            this._handleResize = this._onResize.bind(this);
            this._handleMouseMove = this._onMouseMove.bind(this);
            this._handleMouseLeave = this._onMouseLeave.bind(this);

            window.addEventListener('resize', this._handleResize);
            this.canvas.addEventListener('mousemove', this._handleMouseMove);
            this.canvas.addEventListener('mouseleave', this._handleMouseLeave);

            this.init();
        }

        init() {
            this._setupCanvas();
            this.render();
        }

        destroy() {
            window.removeEventListener('resize', this._handleResize);
            if (this.canvas) {
                this.canvas.removeEventListener('mousemove', this._handleMouseMove);
                this.canvas.removeEventListener('mouseleave', this._handleMouseLeave);
            }
        }

        update() {
            this._setupCanvas();
            this.render();
        }

        _setupCanvas() {
            const dpr = window.devicePixelRatio || 1;
            const rect = this.canvas.getBoundingClientRect();
            const width = rect.width || this.canvas.width || 600;
            const height = rect.height || this.canvas.height || 320;

            this.canvas.width = width * dpr;
            this.canvas.height = height * dpr;
            this.ctx.resetTransform && this.ctx.resetTransform();
            this.ctx.scale(dpr, dpr);
            this.width = width;
            this.height = height;
        }

        _onResize() {
            this._setupCanvas();
            this.render();
        }

        _onMouseMove(e) {
            const rect = this.canvas.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;
            this.hoverPos = { x, y };
            this.render();
        }

        _onMouseLeave() {
            this.hoverPos = null;
            this.render();
        }

        render() {
            const ctx = this.ctx;
            const w = this.width;
            const h = this.height;

            ctx.clearRect(0, 0, w, h);

            const datasets = this.data.datasets || [];
            const labels = this.data.labels || [];
            if (!labels.length || !datasets.length) {
                ctx.fillStyle = "#94a3b8";
                ctx.font = "13px -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, sans-serif";
                ctx.textAlign = "center";
                ctx.fillText("No operational data available for this range", w / 2, h / 2);
                return;
            }

            const isStacked = !!(this.options.scales && this.options.scales.x && this.options.scales.x.stacked);
            const padLeft = 45;
            const padRight = 20;
            const padTop = 35;
            const padBottom = 40;

            const plotW = w - padLeft - padRight;
            const plotH = h - padTop - padBottom;

            // 1. Draw Legend
            this._drawLegend(ctx, w, datasets);

            // 2. Compute Max Value for Scaling
            let maxVal = 0;
            if (isStacked) {
                for (let i = 0; i < labels.length; i++) {
                    let sum = 0;
                    for (const ds of datasets) {
                        sum += (ds.data && ds.data[i] !== undefined) ? Number(ds.data[i]) || 0 : 0;
                    }
                    if (sum > maxVal) maxVal = sum;
                }
            } else {
                for (const ds of datasets) {
                    for (const v of ds.data || []) {
                        const num = Number(v) || 0;
                        if (num > maxVal) maxVal = num;
                    }
                }
            }
            if (maxVal <= 0) maxVal = 10;
            maxVal = Math.ceil(maxVal * 1.15); // headroom

            // 3. Grid & Y-Axis
            const yTicks = 4;
            ctx.strokeStyle = "#334155";
            ctx.fillStyle = "#94a3b8";
            ctx.font = "11px -apple-system, BlinkMacSystemFont, sans-serif";
            ctx.textAlign = "right";
            ctx.lineWidth = 1;

            for (let i = 0; i <= yTicks; i++) {
                const frac = i / yTicks;
                const val = Math.round(maxVal * (1 - frac));
                const y = padTop + frac * plotH;

                ctx.beginPath();
                ctx.moveTo(padLeft, y);
                ctx.lineTo(w - padRight, y);
                ctx.stroke();

                ctx.fillText(String(val), padLeft - 8, y + 4);
            }

            // 4. X-Axis Ticks & Labels
            const catCount = labels.length;
            const catW = plotW / catCount;

            ctx.textAlign = "center";
            for (let i = 0; i < catCount; i++) {
                // Show every nth label if too dense
                const step = catCount > 16 ? 2 : 1;
                if (i % step === 0) {
                    const x = padLeft + (i + 0.5) * catW;
                    ctx.fillText(labels[i], x, h - padBottom + 16);
                }
            }

            // 5. Draw Bars or Lines
            let activeTooltip = null;

            if (this.type === 'line') {
                for (const ds of datasets) {
                    ctx.strokeStyle = ds.borderColor || "#38bdf8";
                    ctx.lineWidth = 2;
                    ctx.beginPath();

                    for (let i = 0; i < catCount; i++) {
                        const v = Number(ds.data[i]) || 0;
                        const x = padLeft + (i + 0.5) * catW;
                        const y = padTop + plotH * (1 - v / maxVal);
                        if (i === 0) ctx.moveTo(x, y);
                        else ctx.lineTo(x, y);
                    }
                    ctx.stroke();
                }
            } else {
                // Bar Chart
                const barPad = catW * 0.2;
                const availableBarW = catW - barPad;

                for (let i = 0; i < catCount; i++) {
                    const catX = padLeft + i * catW + barPad / 2;
                    const mouseInCat = this.hoverPos && (this.hoverPos.x >= padLeft + i * catW) && (this.hoverPos.x < padLeft + (i + 1) * catW);

                    if (isStacked) {
                        let curBaseY = padTop + plotH;
                        for (let d = 0; d < datasets.length; d++) {
                            const ds = datasets[d];
                            const v = Number(ds.data[i]) || 0;
                            const bH = (v / maxVal) * plotH;
                            const bY = curBaseY - bH;

                            ctx.fillStyle = ds.backgroundColor || "#38bdf8";
                            ctx.fillRect(catX, bY, availableBarW, bH);
                            curBaseY = bY;
                        }
                    } else {
                        const barW = availableBarW / datasets.length;
                        for (let d = 0; d < datasets.length; d++) {
                            const ds = datasets[d];
                            const v = Number(ds.data[i]) || 0;
                            const bH = (v / maxVal) * plotH;
                            const bX = catX + d * barW;
                            const bY = padTop + plotH - bH;

                            ctx.fillStyle = ds.backgroundColor || "#38bdf8";
                            ctx.fillRect(bX, bY, barW - 1, bH);
                        }
                    }

                    if (mouseInCat) {
                        // Highlight slice
                        ctx.fillStyle = "rgba(255, 255, 255, 0.05)";
                        ctx.fillRect(padLeft + i * catW, padTop, catW, plotH);

                        activeTooltip = {
                            label: labels[i],
                            x: Math.min(w - 120, Math.max(padLeft, this.hoverPos.x + 10)),
                            y: Math.min(h - 80, Math.max(padTop, this.hoverPos.y - 10)),
                            items: datasets.map(ds => ({
                                label: ds.label || "Value",
                                val: Number(ds.data[i]) || 0,
                                color: ds.backgroundColor || ds.borderColor || "#38bdf8"
                            }))
                        };
                    }
                }
            }

            // 6. Draw Tooltip
            if (activeTooltip) {
                this._drawTooltip(ctx, activeTooltip);
            }
        }

        _drawLegend(ctx, w, datasets) {
            ctx.font = "12px -apple-system, BlinkMacSystemFont, sans-serif";
            ctx.textAlign = "left";
            let totalW = 0;

            const items = datasets.map(ds => {
                const label = ds.label || "";
                const textW = ctx.measureText(label).width;
                const itemW = 16 + textW + 16;
                totalW += itemW;
                return { label, color: ds.backgroundColor || ds.borderColor || "#38bdf8", itemW };
            });

            let curX = Math.max(45, (w - totalW) / 2);
            const curY = 18;

            for (const it of items) {
                ctx.fillStyle = it.color;
                ctx.fillRect(curX, curY - 9, 10, 10);
                ctx.fillStyle = "#cbd5e1";
                ctx.fillText(it.label, curX + 15, curY);
                curX += it.itemW;
            }
        }

        _drawTooltip(ctx, tip) {
            const lineH = 16;
            const tipW = 135;
            const tipH = 24 + tip.items.length * lineH;

            ctx.save();
            ctx.fillStyle = "rgba(15, 23, 42, 0.95)";
            ctx.strokeStyle = "#475569";
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.roundRect ? ctx.roundRect(tip.x, tip.y, tipW, tipH, 6) : ctx.rect(tip.x, tip.y, tipW, tipH);
            ctx.fill();
            ctx.stroke();

            ctx.fillStyle = "#f8fafc";
            ctx.font = "bold 11px sans-serif";
            ctx.textAlign = "left";
            ctx.fillText(tip.label, tip.x + 8, tip.y + 16);

            ctx.font = "11px sans-serif";
            for (let i = 0; i < tip.items.length; i++) {
                const it = tip.items[i];
                const itemY = tip.y + 32 + i * lineH;
                ctx.fillStyle = it.color;
                ctx.fillRect(tip.x + 8, itemY - 8, 8, 8);
                ctx.fillStyle = "#cbd5e1";
                ctx.fillText(`${it.label}: ${it.val}m`, tip.x + 22, itemY);
            }
            ctx.restore();
        }
    }

    return Chart;
}));
